function Quiz({data,mutate,busy}:any){const [answers,setAnswers]=useState<any>({}),[course,setCourse]=useState(data.questions.find((r:Row)=>r.data.published)?.data.course||'');const qs=data.questions.filter((r:Row)=>r.data.published&&r.data.course===course),history=data.docs.filter((r:Row)=>r.kind==='quiz');async function submit(){await mutate('quiz',{data:{answers,course}})}return <><Head tag="KNOWLEDGE CHECK" title={L('Kiểm tra kiến thức nội bộ','内部知识测试','Internal knowledge check')} desc={L('Bài luyện tập, được làm lại. Chấm trên máy chủ; không thay thế chứng nhận O-ELITE LV1.','可重做的练习测试，服务器评分；不代替O-ELITE LV1认证。','Repeatable practice quiz, graded on the server; does not replace O-ELITE LV1.')}/><div className="card"><Field label={L('Khóa kiểm tra','测试课程','Quiz course')}><select className="fieldinput" value={course} onChange={e=>{setCourse(e.target.value);setAnswers({})}}>{data.courses.filter((c:Row)=>data.questions.some((q:Row)=>q.data.published&&q.data.course===c.id)).map((c:Row)=><option key={c.id} value={c.id}>{T(c.data.title)}</option>)}</select></Field>{qs.map((r:Row,i:number)=><div className="q" key={r.id}><h3>{i+1}. {T(r.data.question)}</h3>{r.data.choices.map((c:any,j:number)=><label className="option" key={j}><input type="radio" name={r.id} disabled={data.me.role!=='trainee'} checked={answers[r.id]===j} onChange={()=>setAnswers({...answers,[r.id]:j})}/>{T(c)}</label>)}</div>)}{!qs.length?<Empty/>:data.me.role==='trainee'?<button disabled={busy} onClick={submit}>{L('Nộp bài','提交答案','Submit answers')}</button>:<div className="notice">{L('Chỉ tài khoản trainee được làm bài; các vai trò khác xem đề theo quyền.','仅trainee可答题。','Only trainee accounts may take the quiz.')}</div>}</div>{history.length>0&&<div className="card" style={{marginTop:20}}><h2>{L('Lịch sử luyện tập','练习历史','Practice history')}</h2>{history.map((r:Row)=><details key={r.id}><summary>{r.data.score}/100 · {dateText(r.data.at)}</summary>{r.data.snapshot.map((q:any,i:number)=><p key={i}>{T(q.question)}<br/>{L('Đáp án','正确答案','Correct answer')}: {T(q.choices[q.correct])}</p>)}</details>)}</div>}</>}
function Content({data,mutate,busy,lang,refresh}:any){const manageable=data.courses.filter((c:Row)=>data.me.role==='admin'||data.me.courseRights?.[c.id]?.edit||data.me.courseRights?.[c.id]?.upload||data.me.courseRights?.[c.id]?.publish);const [id,setId]=useState(manageable[0]?.id||''),old=data.courses.find((r:Row)=>r.id===id),mayCreate=data.me.role==='admin'||data.me.rights?.createCourse,mayEdit=old?(data.me.role==='admin'||data.me.courseRights?.[old.id]?.edit)&&!old.data.archived:mayCreate;return <><Head tag="CONTENT MANAGEMENT" title={L('Quản lý khóa học & tệp','课程与文件管理','Course & file management')} desc={L('Quyền theo từng người: nội dung, file, xuất bản/xóa và đánh giá.','逐人授权内容、文件、发布归档及评价。','Permissions are assigned per person: content, files, publication/removal and assessment.')}/><div className="card"><select className="fieldinput" value={id} onChange={e=>setId(e.target.value)}>{mayCreate&&<option value="">{L('+ Thêm mô-đun','+ 新增模块','+ Add module')}</option>}{manageable.map((c:Row)=><option key={c.id} value={c.id}>{T(c.data.title)} · v{c.data.version}{c.data.archived?' · '+L('Đã xóa','已归档','Archived'):''}</option>)}</select>{mayEdit&&<ContentForm key={id+':'+(old?.revision||0)+':'+(data.drafts?.find((d:any)=>d.data.course===old?.id&&d.owner===data.me.id)?.revision||0)} old={old} mutate={mutate} busy={busy} mayPublish={data.me.role==='admin'||data.me.courseRights?.[old?.id]?.publish} draft={data.drafts?.find((d:any)=>d.data.course===old?.id&&d.owner===data.me.id&&d.data.status==='pending')}/>}</div>{old&&<><DraftReview key={'draft:'+id+':'+old.revision} data={data} course={old} mutate={mutate} busy={busy} lang={lang}/><Responsibilities data={data} course={old} lang={lang}/><Materials data={data} course={old} mutate={mutate} busy={busy} refresh={refresh} lang={lang}/><CourseLifecycle key={'life:'+id+':'+old.revision} data={data} course={old} mutate={mutate} busy={busy} lang={lang}/>{data.me.role==='admin'&&<CourseRights key={'acl:'+id+':'+(data.acls?.find((r:any)=>r.data.course===id)?.revision||0)} data={data} course={old} mutate={mutate} busy={busy} lang={lang}/>}</>}</>}

function ContentForm({old,mutate,busy,mayPublish,draft}:any){const [v,setV]=useState<any>(draft?.data.proposal||old?.data||{title:['','',''],body:['','',''],evidence:['','',''],traineeTasks:['','',''],trainerTasks:['','',''],resourceNeeds:['','',''],responsibleKeys:[],quantityMode:'stage',start:1,end:1,owner:'VPC',target:0,resource:'',published:false,source:{sheet:'VPC',range:'',values:[]}});const update=(k:string,x:any)=>setV({...v,[k]:x});async function submit(e:React.FormEvent){e.preventDefault();await mutate('course',{id:old?.id,revision:old?.revision,draftRevision:draft?.revision,data:v})}return <form onSubmit={submit}>{['VN','CN','EN'].map((l,i)=><details key={l} open={i===language}><summary>{l}</summary><Field label={L('Tên mô-đun','模块名称','Module title')+' · '+l}><input type="text" required maxLength={300} value={v.title[i]} onChange={e=>update('title',v.title.map((x:string,j:number)=>i===j?e.target.value:x))}/></Field><Field label={L('Nội dung','内容','Content')+' · '+l}><textarea required value={v.body[i]} maxLength={12000} onChange={e=>update('body',v.body.map((x:string,j:number)=>i===j?e.target.value:x))}/></Field><Field label={L('Đầu ra / minh chứng','成果/佐证','Outcomes / evidence')+' · '+l}><textarea value={v.evidence[i]} onChange={e=>update('evidence',v.evidence.map((x:string,j:number)=>i===j?e.target.value:x))}/></Field>{['traineeTasks','trainerTasks','resourceNeeds'].map(k=><Field key={k} label={({traineeTasks:L('Học viên phải làm','学员任务','Trainee tasks'),trainerTasks:L('Trainer hướng dẫn & kiểm tra','导师指导与检查','Trainer guidance & checks'),resourceNeeds:L('Nguồn lực','资源准备','Resources')} as any)[k]+' · '+l}><textarea value={v[k]?.[i]||''} maxLength={12000} onChange={e=>update(k,(v[k]||['','','']).map((x:string,j:number)=>i===j?e.target.value:x))}/></Field>)}</details>)}<div className="split"><Field label={L("Ngày bắt đầu","开始日","Start day")}><input type="number" min="1" max="90" required value={v.start} onChange={e=>update('start',+e.target.value)}/></Field><Field label={L("Ngày kết thúc","结束日","End day")}><input type="number" min={v.start} max="90" required value={v.end} onChange={e=>update('end',+e.target.value)}/></Field><Field label={L('Phụ trách','负责人','Responsible')}><input type="text" value={v.owner} onChange={e=>update('owner',e.target.value)}/></Field><Field label={L('Mục tiêu số lượng (0 nếu không áp dụng)','数量目标（不适用为0）','Quantity target (0 if not applicable)')}><input type="number" min="0" value={v.target} onChange={e=>update('target',+e.target.value)}/></Field></div><Field label={L('Link học liệu chính thức HTTPS','正式课件HTTPS链接','Official HTTPS material link')}><input type="url" className="fieldinput" value={v.resource} onChange={e=>update('resource',e.target.value)}/></Field><label><input type="checkbox" disabled={!mayPublish} checked={v.published} onChange={e=>update('published',e.target.checked)}/>{L('Xuất bản cho trainee/trainer','向trainee/trainer发布','Publish to trainees/trainers')}</label><div className="actions"><button disabled={busy}>{mayPublish?L('Lưu phiên bản mới','保存新版本','Save new version'):old?.data.published?L('Gửi bản sửa chờ duyệt','提交修改待审核','Submit revision for approval'):L('Lưu bản nháp','保存草稿','Save draft')}</button></div><div className="note">{L('Lưu tạo phiên bản mới và nhật ký thay đổi; kết quả học cũ giữ phiên bản đã hoàn thành. Không tự hoàn thành lại bài.','保存生成新版本并留痕，旧学习结果保留原版本，不自动重新完成。','Saving creates a new version and audit trail. Prior completions keep their recorded version and are not automatically repeated.')}</div></form>}
function QuestionEditor({data,mutate,busy}:any){const editable=data.questions.filter((q:Row)=>data.me.role==='admin'||data.me.courseRights?.[q.data.course]?.edit);const [id,setId]=useState(editable[0]?.id||''),old=editable.find((r:Row)=>r.id===id);return <><Head tag="QUESTION BANK" title={L('Ngân hàng câu hỏi','题库管理','Question bank')} desc={L('Câu hỏi hiện tại là nội bộ luyện tập; cập nhật không đổi kết quả đã thi.','当前题库用于内部练习，更新不改变历史答题结果。','Current questions are for internal practice. Updates do not change earlier attempts.')}/><div className="card"><select className="fieldinput" value={id} onChange={e=>setId(e.target.value)}><option value="">{L('+ Thêm câu hỏi','+ 新增题目','+ Add question')}</option>{editable.map((r:Row)=><option value={r.id} key={r.id}>{T(r.data.question)}</option>)}</select><QuestionForm key={id+':'+(old?.revision||0)} old={old} mutate={mutate} busy={busy} data={data}/></div></>}
function QuestionForm({old,mutate,busy,data}:any){const [v,setV]=useState<any>(old?.data||{course:data.courses.find((c:Row)=>data.me.role==='admin'||data.me.courseRights?.[c.id]?.edit)?.id||'',question:['','',''],choices:[['','',''],['','',''],['','','']],correct:0,published:false});const publisher=data.me.role==='admin'||data.me.courseRights?.[v.course]?.publish;async function submit(e:React.FormEvent){e.preventDefault();await mutate('question',{id:old?.id,revision:old?.revision,data:v})}return <form onSubmit={submit}><Field label={L('Khóa học','课程','Course')}><select className="fieldinput" value={v.course} onChange={e=>setV({...v,course:e.target.value})}>{data.courses.filter((c:Row)=>!c.data.archived&&(data.me.role==='admin'||data.me.courseRights?.[c.id]?.edit)).map((c:Row)=><option key={c.id} value={c.id}>{T(c.data.title)}</option>)}</select></Field>{['VN','CN','EN'].map((l,i)=><details key={l} open={i===language}><summary>{l}</summary><Field label={L('Câu hỏi','题目','Question')+' · '+l}><textarea required maxLength={1000} value={v.question[i]} onChange={e=>setV({...v,question:v.question.map((x:string,j:number)=>j===i?e.target.value:x)})}/></Field>{v.choices.map((c:string[],j:number)=><Field key={j} label={String.fromCharCode(65+j)+' · '+l}><input type="text" maxLength={500} required value={c[i]} onChange={e=>setV({...v,choices:v.choices.map((x:string[],n:number)=>j===n?x.map((y,k)=>k===i?e.target.value:y):x)})}/></Field>)}</details>)}<Field label={L('Đáp án đúng','正确答案','Correct answer')}><select className="fieldinput" value={v.correct} onChange={e=>setV({...v,correct:+e.target.value})}>{v.choices.map((_:any,i:number)=><option key={i} value={i}>{String.fromCharCode(65+i)}</option>)}</select></Field><label><input type="checkbox" disabled={!publisher} checked={v.published} onChange={e=>setV({...v,published:e.target.checked})}/>{L('Đưa vào bài luyện tập','纳入练习测试','Include in practice quiz')}</label><div className="actions"><button disabled={busy||old?.data.published&&!publisher}>{L('Lưu câu hỏi','保存题目','Save question')}</button></div>{!publisher&&old?.data.published&&<p className="notice">{L('Đề đã xuất bản: cần người có quyền xuất bản chỉnh sửa. Bạn có thể tạo câu hỏi nháp mới.','已发布题目需发布权限才能修改，可新建草稿题目。','Published questions require a publisher to edit. You may create a new draft question.')}</p>}</form>}
